/**
 * One term-and-definition pair, laid out as a two-track grid: a term track that may shrink to
 * 9rem and grow to 14rem, and the definition taking the rest. The `<div>` wrapping each dt/dd
 * pair is the markup's, so that the outer `<dl>` has one box per row to stack — the same shape
 * `profile` uses, and for the same reason.
 */
export const definitionRowRow = cva([
  "grid",
  "[grid-template-columns:minmax(9rem,_14rem)_1fr]",
  "gap-space-7",
  "py-space-4",
  "px-pad",
  "[border-bottom:var(--rule)]",
  /* Under `@media (max-width: 620px)` (`below-620`) — Stacked. A term track that has shrunk
     to 9rem leaves a definition column too narrow to read, so below 620px the pair becomes
     two lines — and the gap goes with it: `space-7` is the air between two things side by
     side, and stacked it would put a paragraph's worth of it between a heading and the line
     it heads. */
  "[@media(max-width:620px)]:[grid-template-columns:1fr]",
  "[@media(max-width:620px)]:gap-space-1",
  "[&:last-child]:[border-bottom:0]",
  /* `.tools__row dt` — The skill group's name, in the display family at body size and
     uppercase — a heading for the line beside it rather than a label above it, which is
     what `align-self: center` records: the term sits on the optical middle of a definition
     that may run to three lines. */
  "[&_dt]:font-display",
  "[&_dt]:font-extrabold",
  "[&_dt]:[font-variation-settings:var(--width-body)]",
  "[&_dt]:text-step-base",
  "[&_dt]:uppercase",
  "[&_dt]:text-content-primary",
  "[&_dt]:[align-self:center]",
  /* `.tools__row dd` — The list of tools. One declaration: the `<dd>`'s own margin is
     already off in the foundation reset, and its colour is the page's body ink. */
  "[&_dd]:text-step-md",
]);

export type DefinitionRowRowProps = { className?: string } & Omit<ComponentPropsWithRef<"div">, "className">;

/** The `.tools__row` half of the pattern in components/definition-row/spec.md: a <div>. */
export function DefinitionRowRow({ className, ...rest }: DefinitionRowRowProps) {
  return <div className={cx(definitionRowRow(), className)} {...rest} />;
}
